void computeForces(const std::vector<vec3>& positions, std::vector<vec3>& forces, double boxSize, double cutoffRadius, double epsilon, double sigma) {
    // Reset forces to zero
    for (auto& force : forces) {
        force = vec3(0, 0, 0);
    }

    const double cutoffSquared = cutoffRadius * cutoffRadius;
    const double sigmaSquared = sigma * sigma;
    const double sigma6 = sigmaSquared * sigmaSquared * sigmaSquared;
    const double sigma12 = sigma6 * sigma6;

    for (size_t i = 0; i < positions.size(); ++i) {
        for (size_t j = i + 1; j < positions.size(); ++j) {
            // Compute minimum image distance
            vec3 rij = positions[j] - positions[i];
            rij.x -= boxSize * std::round(rij.x / boxSize);
            rij.y -= boxSize * std::round(rij.y / boxSize);
            rij.z -= boxSize * std::round(rij.z / boxSize);

            double rijSquared = rij.lengthSquared();

            // Check if particles are within cutoff
            if (rijSquared < cutoffSquared) {
                double rijInvSquared = 1.0 / rijSquared;
                double rijInv6 = rijInvSquared * rijInvSquared * rijInvSquared;
                double rijInv12 = rijInv6 * rijInv6;

                // Compute LJ force magnitude
                double forceMagnitude = 24.0 * epsilon * (2.0 * sigma12 * rijInv12 - sigma6 * rijInv6) * rijInvSquared;

                // Update forces
                vec3 forceVec = rij * forceMagnitude;
                forces[i] += forceVec;
                forces[j] -= forceVec;
            }
        }
    }
}

